const main = async () => {
  console.log('🧹 Clearing existing product-related data...');
  await prisma.wishlistItem.deleteMany({});
  await prisma.review.deleteMany({});
  await prisma.orderItem.deleteMany({});
  await prisma.cartItem.deleteMany({});
  await prisma.product.deleteMany({});
  await prisma.category.deleteMany({});

  const categoryRecords = new Map<string, string>();

  // Create categories
  for (const category of categories) {
    const record = await prisma.category.create({
      data: category,
    });

    categoryRecords.set(record.name, record.id);
  }

  // Create/update products
  for (const product of products) {
    const categoryId = categoryRecords.get(product.category);

    if (!categoryId) {
      console.warn(`Category not found: ${product.category}`);
      continue;
    }

    const existingProduct = await prisma.product.findFirst({
      where: { name: product.name },
    });

    const productData = {
      name: product.name,
      description: product.description,
      price: product.price,
      image: product.image,
      images: Array.isArray(product.imageViews) && product.imageViews.length > 0
        ? product.imageViews
        : product.image
          ? [product.image]
          : [],
      brand: product.brand,
      stock: product.stock,
      rating: product.rating,
      reviewCount: product.reviewCount,
      isActive: true,
      categoryId,
    };

    if (existingProduct) {
      await prisma.product.update({
        where: { id: existingProduct.id },
        data: productData,
      });
    } else {
      await prisma.product.create({
        data: productData,
      });
    }
  }

  console.log(`✅ Seed complete: ${categories.length} categories, ${products.length} products`);
  console.log('🖼️ Each product has 4 prepared image views in imageViews (not stored with the current Prisma schema).');
};

main()
  .catch((error) => {
    console.error('❌ Seed failed:', error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });